-- Lot 219 : payloads 541 a 570 sur 1299.
--
-- Chaque commande recoit un texte propre a ChatGPT, a Claude et a Gemini.
-- Rien n'est supprime : l'ancienne version quitte le courant et reste lisible
-- dans l'historique, ce qui suffit a revenir en arriere.

drop table if exists lot_v5_payloads;
create temporary table lot_v5_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-084","moteur":"chatgpt","payload":"[RaccourcIA — /weatherchange]\n\nMISSION\nModifier la météo d'une scène. Applique les conséquences de la météo sur ciel, surfaces, visibilité et lumière. Conserve sujet et lieu, sans catastrophes ajoutées.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quelle ambiance ou fonction doit guider l’aménagement du lieu ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Changer la météo » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Applique les conséquences de la météo sur ciel, surfaces, visibilité et lumière. Conserve sujet et lieu, sans catastrophes ajoutées. Le format par défaut est 16:9 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve la structure, les ouvertures, la perspective, la géométrie et tous les éléments hors périmètre de la modification.\n\nÉVITER\nÉvite murs ou ouvertures déplacés sans demande, mobilier à mauvaise échelle, perspective cassée, circulation impossible et lumière incohérente. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"026c7a20cc11a44da5faaad03d8ddbbbf231940b00410f22585d8ec2539be448"},{"ref":"RCI-IMG-084","moteur":"claude","payload":"[RaccourcIA — /weatherchange]\n\nMISSION\nModifier la météo d'une scène. Applique les conséquences de la météo sur ciel, surfaces, visibilité et lumière. Conserve sujet et lieu, sans catastrophes ajoutées.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quelle ambiance ou fonction doit guider l’aménagement du lieu ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Changer la météo » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Applique les conséquences de la météo sur ciel, surfaces, visibilité et lumière. Conserve sujet et lieu, sans catastrophes ajoutées. Le format par défaut est 16:9 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve la structure, les ouvertures, la perspective, la géométrie et tous les éléments hors périmètre de la modification.\n\nÉVITER\nÉvite murs ou ouvertures déplacés sans demande, mobilier à mauvaise échelle, perspective cassée, circulation impossible et lumière incohérente. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"0148561f01b3275f88df8a398529caead5eff0f59318c09dcc6180e27c77f989"},{"ref":"RCI-IMG-084","moteur":"gemini","payload":"[RaccourcIA — /weatherchange]\n\nMISSION\nModifier la météo d'une scène. Applique les conséquences de la météo sur ciel, surfaces, visibilité et lumière. Conserve sujet et lieu, sans catastrophes ajoutées.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte. Relie clairement chaque référence à son rôle : sujet, style, marque, données ou composition. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quelle ambiance ou fonction doit guider l’aménagement du lieu ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Changer la météo » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Applique les conséquences de la météo sur ciel, surfaces, visibilité et lumière. Conserve sujet et lieu, sans catastrophes ajoutées. Le format par défaut est 16:9 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve la structure, les ouvertures, la perspective, la géométrie et tous les éléments hors périmètre de la modification.\n\nÉVITER\nÉvite murs ou ouvertures déplacés sans demande, mobilier à mauvaise échelle, perspective cassée, circulation impossible et lumière incohérente. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si la génération ou l’édition visuelle n’est pas disponible, livre un prompt final compatible avec un moteur d’image et précise le statut réel de la sortie.","sha256":"5d1b44fa5e3175c85c51130fd18773cfa49326d726db530a91776caac830c9ca"},{"ref":"RCI-IMG-085","moteur":"chatgpt","payload":"[RaccourcIA — /reflectionfix]\n\nMISSION\nRéduire ou reconstruire des reflets gênants. Réduis le reflet ciblé et conserve les reflets nécessaires à la lecture du verre ou du métal. Ne prétends pas retrouver avec certitude un détail entièrement masqué.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quelle intensité d’effet souhaites-tu : subtile, marquée ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Corriger les reflets » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Réduis le reflet ciblé et conserve les reflets nécessaires à la lecture du verre ou du métal. Ne prétends pas retrouver avec certitude un détail entièrement masqué. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve le sujet, sa silhouette, ses proportions et ses détails distinctifs; ne transforme que l’effet demandé.\n\nÉVITER\nÉvite effet générique, sujet méconnaissable, texture répétitive, contours fusionnés, surtraitement et éléments ajoutés sans intention. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"bf514f013ff3ea7c4f68a3cc57835ebf38ed4a6b4b28e009d74ab226ad419158"},{"ref":"RCI-IMG-085","moteur":"claude","paylo